#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
    vector<double> a={1,2,2},b={2,1,3};
    double norm=0;
    for (double x:a)norm+=x*x;
    norm=sqrt(norm);
    for (double& x:a)x/=norm;
    double projection=0;
    for (int i=0;i<3;i++)projection+=a[i]*b[i];
    for (int i=0;i<3;i++)b[i]-=projection*a[i];
    double second=0;
    for (double x:b)second+=x*x;
    second=sqrt(second);
    if (second<1e-12)return 1;
    for (double& x:b)x/=second;
    double orthogonal=0;
    for (int i=0;i<3;i++)orthogonal+=a[i]*b[i];
    cout<<orthogonal<<"\n";
    return 0;
}

