#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
    double a[2][2]={{4,1},{1,3}},b[2]={1,2},x[2]={0,0},r[2]={1,2},p[2]={1,2};
    double rr=r[0]*r[0]+r[1]*r[1];
    for (int step=0;step<2;step++){
        double ap[2]={a[0][0]*p[0]+a[0][1]*p[1],a[1][0]*p[0]+a[1][1]*p[1]};
        double denom=p[0]*ap[0]+p[1]*ap[1];
        if (fabs(denom)<1e-12)break;
        double alpha=rr/denom;
        for (int i=0;i<2;i++){
            x[i]+=alpha*p[i];
            r[i]-=alpha*ap[i];
        }
        double next=r[0]*r[0]+r[1]*r[1];
        if (next<1e-14)break;
        double beta=next/rr;
        for (int i=0;i<2;i++)p[i]=r[i]+beta*p[i];
        rr=next;
    }
    cout<<x[0]<<" "<<x[1]<<"\n";
    return 0;
}

