#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
    double S=100,K=100,r=0.02,T=1,marketCall=9;
    double left=0.0001,right=2;
    for (int k=0;k<70;k++){
        double sigma=(left+right)/2;
        double d1=(log(S/K)+(r+0.5*sigma*sigma)*T)/(sigma*sqrt(T));
        double d2=d1-sigma*sqrt(T);
        double cdf1=0.5*erfc(-d1/sqrt(2.0)),cdf2=0.5*erfc(-d2/sqrt(2.0));
        double price=S*cdf1-K*exp(-r*T)*cdf2;
        if (price>marketCall)right=sigma;
        else left=sigma;
    }
    cout<<fixed<<setprecision(8)<<(left+right)/2<<"\n";
    return 0;
}
